ENSC 316 – Assignment 02 (MATLAB)
Q2 – Exercise 1.12: Charged hemisphere
Integral computed (ring at polar angle θ has radius a·sinθ, height a·cosθ, charge dQ = ρs·2πa²·sinθ dθ):

E_z(z) = \frac{\rho_s a^2}{2\varepsilon_0}\int_0^{\pi/2} \frac{\sin\theta\,(z - a\cos\theta)}{\left(a^2 + z^2 - 2az\cos\theta\right)^{3/2}}\,d\theta

Evaluated with the midpoint rule over N rings.

% MATLAB Exercise 1.12 - Charged hemisphere, numerical integration in theta

%

% Ring at polar angle theta: radius a*sin(theta), height a*cos(theta),

% charge dQ = rho_s*2*pi*a^2*sin(theta)*dtheta. Summing the on-axis ring fields:

%

% Ez(z) = rho_s*a^2/(2*eps0) * Int_0^(pi/2) sin(theta)*(z - a*cos(theta))

% / (a^2 + z^2 - 2*a*z*cos(theta))^(3/2) dtheta

%

% evaluated with the midpoint rule (1.19) using N rings.

clear; clc;

eps0 = 8.8541878128e-12;



rhos = input(&#039;Surface charge density rho_s [C/m^2]: &#039;);

a = input(&#039;Radius of the hemispherical shell a [m]: &#039;);

z = input(&#039;z-coordinate of the field point [m]: &#039;);

N = input(&#039;Number of rings N: &#039;);



dtheta = (pi/2)/N;

theta = ((1:N) - 0.5)*dtheta; % centres of the N segments

f = sin(theta).*(z - a*cos(theta)) ./ (a^2 + z^2 - 2*a*z*cos(theta)).^1.5;

Enum = rhos*a^2/(2*eps0) * sum(f)*dtheta;



Ea = rhos*a^2/(2*eps0*z^2) * (a/sqrt(z^2 + a^2) + (z - a)/abs(z - a));

err = abs((Ea - Enum)/Ea)*100;



fprintf(&#039;\nNumerical Ez = %.6e V/m\n&#039;, Enum);

fprintf(&#039;Analytic Ez = %.6e V/m\n&#039;, Ea);

fprintf(&#039;Relative error = %.4e %%\n&#039;, err);

Output (ρs = 1e-9 C/m², a = 1 m, N = 500):

z = 5 m

Numerical Ez = 2.701811e+00 V/m

Analytic Ez = 2.701809e+00 V/m

Relative error = 6.5938e-05 %



z = 0.5 m

Numerical Ez = -2.384708e+01 V/m

Analytic Ez = -2.384698e+01 V/m

Relative error = 4.1740e-04 %

Q3 – Exercise 1.13: Line charge with quiver

% MATLAB Exercise 1.13 - E-field of a finite line charge (along x, centred

% at the origin) by numerical superposition of point charges, shown with quiver.

clear; clc;

eps0 = 8.8541878128e-12;

k = 1/(4*pi*eps0);



N = input(&#039;Number of subdivisions of the line N: &#039;);

L = input(&#039;Length of the line L [cm]: &#039;)/100;

Q = input(&#039;Total charge Q [nC]: &#039;)*1e-9;



% 10 x 10 field-point grid; an even point count keeps y = 0 off the grid

[X, Y] = meshgrid(linspace(-0.6*L, 0.6*L, 10), linspace(-0.2*L, 0.2*L, 10));



dQ = Q/N;

xs = -L/2 + ((1:N) - 0.5)*L/N; % source points = segment centres

Ex = zeros(size(X));

Ey = zeros(size(X));

for i = 1:size(X, 1) % field point row

for j = 1:size(X, 2) % field point column

for n = 1:N % source point

Rx = X(i,j) - xs(n);

Ry = Y(i,j);

R3 = (Rx^2 + Ry^2)^1.5;

Ex(i,j) = Ex(i,j) + k*dQ*Rx/R3;

Ey(i,j) = Ey(i,j) + k*dQ*Ry/R3;

end

end

end



% Diagnostics: compare with the closed-form field of a finite line

lam = Q/L;

r1 = sqrt((X + L/2).^2 + Y.^2); % distance to left end

r2 = sqrt((X - L/2).^2 + Y.^2); % distance to right end

ExA = k*lam*(1./r2 - 1./r1);

EyA = k*lam./Y.*((X + L/2)./r1 - (X - L/2)./r2);

relErr = hypot(Ex - ExA, Ey - EyA)./hypot(ExA, EyA)*100;

fprintf(&#039;\nN = %d, L = %g m, Q = %g C\n&#039;, N, L, Q);

fprintf(&#039;|E| range on grid: %.4e to %.4e V/m\n&#039;, min(hypot(Ex,Ey),[],&#039;all&#039;), max(hypot(Ex,Ey),[],&#039;all&#039;));

fprintf(&#039;Max relative error vs analytic: %.4e %%\n&#039;, max(relErr, [], &#039;all&#039;));



figure;

quiver(X, Y, Ex, Ey);

hold on;

plot([-L/2 L/2], [0 0], &#039;r&#039;, &#039;LineWidth&#039;, 3);

axis equal;

xlabel(&#039;x [m]&#039;); ylabel(&#039;y [m]&#039;);

title(sprintf(&#039;E-field of a line charge (N = %d, Q = %g nC, L = %g cm)&#039;, N, Q*1e9, L*100));

legend(&#039;E&#039;, &#039;line charge&#039;);

N = 1000, Q = 1 nC, L = 100 cm:

Q4 – Exercise 1.16: Finite vs infinite line charge

% MATLAB Exercise 1.16 - Finite vs infinite line charge.

% Finite line along z, centred at the origin; field points on the +x axis,

% so theta2 = -theta1 and only the x-component of (1.24) survives.

clear; clc;

eps0 = 8.8541878128e-12;



L = input(&#039;Length of the line L [cm]: &#039;)/100;

rhol = input(&#039;Line charge density [nC/m]: &#039;)*1e-9;



D = linspace(0.1*L, 2*L, 5000);

sinT2 = (L/2)./sqrt(D.^2 + (L/2)^2);

Efin = rhol./(4*pi*eps0*D) .* 2.*sinT2; % Eq. (1.24)

Einf = rhol./(2*pi*eps0*D); % Eq. (1.25)

err = (Einf - Efin)./Efin*100;



kmax = D(find(err &gt; 10, 1))/L;

fprintf(&#039;\nL = %g m, rho_l = %g C/m\n&#039;, L, rhol);

fprintf(&#039;Error at k = 0.1: %.3f %%, at k = 2: %.3f %%\n&#039;, err(1), err(end));

fprintf(&#039;kmax (error &gt; 10%%) = %.4f, Dmax = %.4f m\n&#039;, kmax, kmax*L);



figure;

plot(D/L, Efin, &#039;-&#039;, D/L, Einf, &#039;--&#039;);

xline(kmax, &#039;-&#039;, sprintf(&#039;k = kmax = %.3f&#039;, kmax));

xlabel(&#039;k = D/L&#039;); ylabel(&#039;E [V/m]&#039;);

title(&#039;Comparison of E-fields due to finite and infinite lines of charge&#039;);

legend(&#039;Finite&#039;, &#039;Infinite&#039;);

L = 100 cm, ρl = 1 nC/m. The error passes 10% at kmax = 0.229 (theory: √0.21 / 2 = 0.2291).

